{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "Instance Metadata Service Version 1 is enabled by default, which can be a security risk as it allows unrestricted access to instance metadata."
    },
    {
      "check_id": "CKV_AWS_389",
      "title": "Ensure AWS Auto Scaling group launch configuration doesn't have public IP address assignment enabled",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "Public IP address assignment is enabled by default, which can expose instances to the internet and increase the attack surface."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "Data stored in the instance's Elastic Block Store (EBS) is not explicitly encrypted, which can lead to data exposure if the storage is compromised."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"levelup-launchconfig\" {\n  name_prefix     = \"levelup-launchconfig\"\n  image_id        = lookup(var.AMIS, var.AWS_REGION)\n  instance_type   = \"t2.micro\"\n  key_name        = aws_key_pair.levelup_key.key_name\n  metadata_options {\n    http_tokens = \"required\"\n  }\n  associate_public_ip_address = false\n  root_block_device {\n    encrypted = true\n  }\n}",
  "fix_summary": "Enabled IMDSv2 by setting http_tokens to 'required', disabled public IP address assignment, and enabled EBS encryption for the root block device."
}
